import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Tiled 3D convolution kernel for:
//   N=16, Cin=3, Cout=64, K=3, stride=1, padding=0, dilation=1
//   Din=Hin=Win=64  =>  Dout=Hout=Wout=62
// Each CTA computes a 16x16 spatial tile of outputs for one (n, oc, od).
// The reusable input footprint (18x18 per ic,kd slice) is staged into
// shared memory once and reused by all 256 threads in the CTA, and the
// 81-element weight slice for the CTA's output channel is cached in
// shared memory once per CTA, removing redundant global memory traffic.
.visible .entry conv3d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr
)
{
    .reg .pred %p<40>;
    .reg .u32 %r<140>;
    .reg .u64 %rd<40>;
    .reg .f32 %f<20>;
    .shared .align 4 .b8 smem_input[1364];
    .shared .align 4 .b8 smem_weight[324];
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [output_ptr];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r1, %tid.x;             // tx (0..7)
    mov.u32 %r2, %tid.y;             // ty (0..7)
    mov.u32 %r3, %ctaid.x;           // bx
    mov.u32 %r4, %ctaid.y;           // by
    mov.u32 %r5, %ctaid.z;           // bz
    mul.lo.u32 %r28, %r4, 16;        // oh_base
    mul.lo.u32 %r29, %r3, 16;        // ow_base
    mul.lo.u32 %r6, %r1, 2;          // tx*2
    mul.lo.u32 %r7, %r2, 2;          // ty*2
    add.u32 %r8, %r29, %r6;          // ow0
    add.u32 %r9, %r8, 1;             // ow1
    add.u32 %r10, %r28, %r7;         // oh0
    add.u32 %r11, %r10, 1;           // oh1
    mad.lo.u32 %r12, %r2, 8, %r1;    // linear_tid (0..63)
    mov.u32 %r13, 62;
    rem.u32 %r14, %r5, %r13;         // od
    div.u32 %r15, %r5, %r13;         // t
    mov.u32 %r16, 64;
    rem.u32 %r17, %r15, %r16;        // oc
    div.u32 %r18, %r15, %r16;        // n
    setp.lt.u32 %p1, %r8, %r13;      // ow0 < 62
    setp.lt.u32 %p2, %r9, %r13;      // ow1 < 62
    setp.lt.u32 %p3, %r10, %r13;     // oh0 < 62
    setp.lt.u32 %p4, %r11, %r13;     // oh1 < 62
    and.pred %p5, %p1, %p3;          // valid00
    and.pred %p6, %p2, %p3;          // valid01
    and.pred %p7, %p1, %p4;          // valid10
    and.pred %p8, %p2, %p4;          // valid11
    or.pred  %p9, %p5, %p6;
    or.pred  %p9, %p9, %p7;
    or.pred  %p9, %p9, %p8;          // any_valid
    mov.u32 %r70, smem_input;
    mov.u32 %r72, smem_weight;
    // ---- cache weight slice for this oc into shared memory (81 elems, 64 threads, 2 passes) ----
    mov.u32 %r80, 0;
WEIGHT_LOOP:
    mad.lo.u32 %r81, %r80, 64, %r12;  // widx
    setp.lt.u32 %p10, %r81, 81;
    @!%p10 bra WEIGHT_SKIP;
    mad.lo.u32 %r82, %r17, 81, %r81;
    mul.wide.u32 %rd4, %r82, 4;
    add.u64 %rd5, %rd2, %rd4;
    ld.global.f32 %f1, [%rd5];
    mad.lo.u32 %r83, %r81, 4, %r72;
    st.shared.f32 [%r83], %f1;
WEIGHT_SKIP:
    add.u32 %r80, %r80, 1;
    setp.lt.u32 %p11, %r80, 2;
    @%p11 bra WEIGHT_LOOP;
    bar.sync 0;
    mov.f32 %f2, 0f00000000;   // acc00
    mov.f32 %f3, 0f00000000;   // acc01
    mov.f32 %f4, 0f00000000;   // acc10
    mov.f32 %f5, 0f00000000;   // acc11
    mov.u32 %r20, 0;                 // ic
IC_LOOP:
    mov.u32 %r21, 0;                 // kd
KD_LOOP:
    add.u32 %r22, %r14, %r21;        // id = od+kd
    // ---- stage input tile (18x18=324) into shared memory, 64 threads, 6 passes ----
    mov.u32 %r90, 0;
INPUT_LOAD_LOOP:
    mad.lo.u32 %r91, %r90, 64, %r12;  // idx
    setp.lt.u32 %p12, %r91, 324;
    @!%p12 bra INPUT_LOAD_SKIP;
    div.u32 %r92, %r91, 18;           // local_h
    rem.u32 %r93, %r91, 18;           // local_w
    add.u32 %r94, %r28, %r92;         // ih
    add.u32 %r95, %r29, %r93;         // iw
    setp.lt.u32 %p13, %r94, 64;
    setp.lt.u32 %p14, %r95, 64;
    and.pred %p15, %p13, %p14;
    mov.f32 %f6, 0f00000000;
    @!%p15 bra INPUT_STORE;
    mad.lo.u32 %r96, %r18, 3, %r20;
    mad.lo.u32 %r97, %r96, 64, %r22;
    mad.lo.u32 %r98, %r97, 64, %r94;
    mad.lo.u32 %r99, %r98, 64, %r95;
    mul.wide.u32 %rd9, %r99, 4;
    add.u64 %rd10, %rd1, %rd9;
    ld.global.f32 %f6, [%rd10];
INPUT_STORE:
    mad.lo.u32 %r101, %r92, 19, %r93;
    mad.lo.u32 %r100, %r101, 4, %r70;
    st.shared.f32 [%r100], %f6;
INPUT_LOAD_SKIP:
    add.u32 %r90, %r90, 1;
    setp.lt.u32 %p16, %r90, 6;
    @%p16 bra INPUT_LOAD_LOOP;
    bar.sync 0;
    @!%p9 bra SKIP_ACC;
    mov.u32 %r50, 0;                 // kh
KH_LOOP:
    mov.u32 %r51, 0;                 // kw
KW_LOOP:
    mad.lo.u32 %r55, %r20, 3, %r21;
    mad.lo.u32 %r56, %r55, 3, %r50;
    mad.lo.u32 %r57, %r56, 3, %r51;
    mad.lo.u32 %r58, %r57, 4, %r72;
    ld.shared.f32 %f7, [%r58];
    add.u32 %r110, %r7, %r50;        // h0 = ty*2+kh
    add.u32 %r111, %r110, 1;         // h1
    add.u32 %r112, %r6, %r51;        // w0 = tx*2+kw
    add.u32 %r113, %r112, 1;         // w1
    mad.lo.u32 %r114, %r110, 19, %r112;
    mad.lo.u32 %r115, %r114, 4, %r70;
    ld.shared.f32 %f8, [%r115];
    fma.rn.f32 %f2, %f8, %f7, %f2;
    mad.lo.u32 %r116, %r110, 19, %r113;
    mad.lo.u32 %r117, %r116, 4, %r70;
    ld.shared.f32 %f9, [%r117];
    fma.rn.f32 %f3, %f9, %f7, %f3;
    mad.lo.u32 %r118, %r111, 19, %r112;
    mad.lo.u32 %r119, %r118, 4, %r70;
    ld.shared.f32 %f10, [%r119];
    fma.rn.f32 %f4, %f10, %f7, %f4;
    mad.lo.u32 %r120, %r111, 19, %r113;
    mad.lo.u32 %r121, %r120, 4, %r70;
    ld.shared.f32 %f11, [%r121];
    fma.rn.f32 %f5, %f11, %f7, %f5;
    add.u32 %r51, %r51, 1;
    setp.lt.u32 %p17, %r51, 3;
    @%p17 bra KW_LOOP;
    add.u32 %r50, %r50, 1;
    setp.lt.u32 %p18, %r50, 3;
    @%p18 bra KH_LOOP;
SKIP_ACC:
    bar.sync 0;
    add.u32 %r21, %r21, 1;
    setp.lt.u32 %p19, %r21, 3;
    @%p19 bra KD_LOOP;
    add.u32 %r20, %r20, 1;
    setp.lt.u32 %p20, %r20, 3;
    @%p20 bra IC_LOOP;
    mad.lo.u32 %r130, %r18, 64, %r17;
    mad.lo.u32 %r131, %r130, 62, %r14;
    and.pred %p30, %p5, %p6;         // both row0 outputs valid -> vectorized store
    mad.lo.u32 %r132, %r131, 62, %r10;
    mad.lo.u32 %r133, %r132, 62, %r8;
    mul.wide.u32 %rd20, %r133, 4;
    add.u64 %rd21, %rd3, %rd20;
    @!%p30 bra ROW0_SCALAR;
    st.global.v2.f32 [%rd21], {%f2, %f3};
    bra ROW0_DONE;
ROW0_SCALAR:
    @!%p5 bra STORE01;
    st.global.f32 [%rd21], %f2;
STORE01:
    @!%p6 bra ROW0_DONE;
    mad.lo.u32 %r134, %r131, 62, %r10;
    mad.lo.u32 %r135, %r134, 62, %r9;
    mul.wide.u32 %rd22, %r135, 4;
    add.u64 %rd23, %rd3, %rd22;
    st.global.f32 [%rd23], %f3;
ROW0_DONE:
    and.pred %p31, %p7, %p8;         // both row1 outputs valid -> vectorized store
    mad.lo.u32 %r136, %r131, 62, %r11;
    mad.lo.u32 %r137, %r136, 62, %r8;
    mul.wide.u32 %rd24, %r137, 4;
    add.u64 %rd25, %rd3, %rd24;
    @!%p31 bra ROW1_SCALAR;
    st.global.v2.f32 [%rd25], {%f4, %f5};
    bra DONE;
ROW1_SCALAR:
    @!%p7 bra STORE11;
    st.global.f32 [%rd25], %f4;
STORE11:
    @!%p8 bra DONE;
    mad.lo.u32 %r138, %r131, 62, %r11;
    mad.lo.u32 %r139, %r138, 62, %r9;
    mul.wide.u32 %rd26, %r139, 4;
    add.u64 %rd27, %rd3, %rd26;
    st.global.f32 [%rd27], %f5;
DONE:
    ret;
